<script setup>
import { ref,computed,onMounted } from 'vue'
import Chart from './Chart.vue'
const data=ref(null),error=ref(''),model=ref('B3'),dimension=ref('Origin')
const colours=['#879aaf','#4178ae','#38cfe8','#f6b44d']
async function load(){error.value='';try{const r=await fetch('/api/experiments');if(!r.ok)throw Error('实验结果暂不可用，请重试。');data.value=await r.json()}catch(e){error.value=e.message}}
onMounted(load)
const rows=computed(()=>Object.entries(data.value?.metrics.test||{}).map(([name,v])=>({name,...v})))
const current=computed(()=>data.value?.metrics.test[model.value])
const basic={textStyle:{color:'#9aaec8'},grid:{left:48,right:25,top:28,bottom:40},tooltip:{trigger:'axis'},xAxis:{type:'value',min:0,max:1},yAxis:{type:'value',min:0,max:1,splitLine:{lineStyle:{color:'#25354c'}}}}
const pr=computed(()=>({...basic,xAxis:{...basic.xAxis,name:'Recall',nameLocation:'middle',nameGap:25},yAxis:{...basic.yAxis,name:'Precision'},legend:{data:rows.value.map(r=>r.name),textStyle:{color:'#c4d4e7'},top:0},series:rows.value.map((r,i)=>({name:r.name,type:'line',showSymbol:false,data:r.pr_curve.map(p=>[p.recall,p.precision]),lineStyle:{color:colours[i],width:2},itemStyle:{color:colours[i]}}))}))
const calibration=computed(()=>({...basic,xAxis:{...basic.xAxis,name:'平均分数',nameLocation:'middle',nameGap:25},yAxis:{...basic.yAxis,name:'实际延误率'},series:[{type:'line',data:[[0,0],[1,1]],showSymbol:false,lineStyle:{type:'dashed',color:'#607893'}},{type:'line',data:(current.value?.reliability||[]).filter(b=>b.n).map(b=>[b.mean_score,b.observed_rate,b.n]),symbolSize:7,lineStyle:{color:'#f6b44d'},itemStyle:{color:'#f6b44d'}}]}))
const groups=computed(()=>(data.value?.groups[dimension.value]||[]).slice().sort((a,b)=>b.n-a.n).slice(0,10))
const fmt=v=>Number(v).toFixed(4)
</script>
<template>
 <div v-if="error" role="alert" class="error">{{error}} <button @click="load">重试</button></div><div v-if="!data&&!error" class="loading">读取已验证的实验产物…</div>
 <div v-if="data">
  <div class="notice">训练：2024-02—04 · 验证：2024-05 · 测试：2024-06 · 历史预热：2024-01 · 随机种子 42 · 独立复算通过</div>
  <section class="panel experiment-table"><div class="panel-heading"><div><h2>统一测试集模型比较</h2><p>{{data.verification.test_rows.toLocaleString()}} 个有效航班 · 主指标为完整 PR 曲线梯形积分面积</p></div><span class="pill">{{data.metrics.version}}</span></div><div class="table-scroll"><table><thead><tr><th>模型</th><th>PR-AUC ↑</th><th>ROC-AUC ↑</th><th>Precision</th><th>Recall</th><th>F1</th><th>Brier ↓</th><th>验证阈值</th></tr></thead><tbody><tr v-for="r in rows" :key="r.name" :class="{highlight:r.name===model}"><td><button @click="model=r.name">{{r.name}} {{r.name===data.metrics.selection.recommended_model?'· 验证集推荐':''}}</button></td><td>{{fmt(r.pr_auc)}}</td><td>{{fmt(r.roc_auc)}}</td><td>{{fmt(r.precision)}}</td><td>{{fmt(r.recall)}}</td><td>{{fmt(r.f1)}}</td><td>{{fmt(r.brier)}}</td><td>{{fmt(r.threshold)}}</td></tr></tbody></table></div></section>
  <p class="comparison-note">B3−B2 测试 PR-AUC：{{data.metrics.b3_minus_b2_pr_auc.toFixed(6)}}。B2 选中深度 5、B3 选中深度 7；测试差值比较各自选优流程，同参数特征增量见下方验证对照。</p>
  <div class="lower-grid experiment-charts"><section class="panel"><div class="panel-heading"><div><h2>Precision–Recall 曲线</h2><p>显示点经过抽样；指标使用全部曲线点计算</p></div></div><Chart :option="pr" label="四组模型PR曲线"/></section><section class="panel"><div class="panel-heading"><div><h2>可靠性图 · {{model}}</h2><p>10 个等宽分箱 · 点击上方模型切换</p></div></div><Chart :option="calibration" label="模型分数可靠性图"/></section></div>
  <div class="main-grid"><section class="panel confusion"><h2>{{model}} 混淆矩阵</h2><p>行：实际标签；列：模型判断 · 分数 ≥ 验证阈值判为延误</p><div class="matrix"><span></span><span>预测未延误</span><span>预测延误</span><span>实际未延误</span><strong>{{current.confusion.tn.toLocaleString()}}</strong><strong class="amber">{{current.confusion.fp.toLocaleString()}}</strong><span>实际延误</span><strong class="amber">{{current.confusion.fn.toLocaleString()}}</strong><strong>{{current.confusion.tp.toLocaleString()}}</strong></div></section><section class="panel paired"><h2>同参数配对验证</h2><p>相同训练样本、随机种子与搜索预算</p><table><thead><tr><th>深度</th><th>B2 PR-AUC</th><th>B3 PR-AUC</th></tr></thead><tbody><tr v-for="c in [0,1]" :key="c"><td>{{c===0?5:7}}</td><td>{{fmt(data.metrics.selection.trials.find(t=>t.model==='B2'&&t.candidate===c).validation.pr_auc)}}</td><td>{{fmt(data.metrics.selection.trials.find(t=>t.model==='B3'&&t.candidate===c).validation.pr_auc)}}</td></tr></tbody></table></section></div>
  <section class="panel error-table"><div class="panel-heading"><div><h2>B3 分组错误分析</h2><p>按样本量列出前 10 组 · 不能用小样本误差推断因果</p></div><select aria-label="错误分析维度" v-model="dimension"><option value="Origin">出发机场</option><option value="dep_hour">计划小时</option><option value="support_band">航线历史支持数</option></select></div><div class="table-scroll"><table><thead><tr><th>分组</th><th>样本量</th><th>误报 FP</th><th>漏报 FN</th><th>Brier</th></tr></thead><tbody><tr v-for="(g,i) in groups" :key="i"><td>{{g[dimension]}}</td><td>{{g.n.toLocaleString()}}</td><td>{{g.fp.toLocaleString()}}</td><td>{{g.fn.toLocaleString()}}</td><td>{{fmt(g.brier)}}</td></tr></tbody></table></div></section>
  <section class="panel engineering"><h2>CSV 与 Parquet 查询实验</h2><div v-if="!data.engineering" class="empty">待运行：尚无工程实验产物。</div><template v-else><p>同一批 {{data.engineering.records.toLocaleString()}} 条清洗记录、相同字段及分组查询；每种格式 3 次，交替执行。结果一致性：{{data.engineering.consistent?'通过':'未通过'}}</p><table><thead><tr><th>格式</th><th>存储体积 MiB</th><th>第1轮 秒</th><th>第2轮 秒</th><th>第3轮 秒</th><th>中位数 秒</th></tr></thead><tbody><tr v-for="f in ['csv','parquet']" :key="f"><td>{{f.toUpperCase()}}</td><td>{{(data.engineering.storage[f].bytes/1048576).toFixed(2)}}</td><td v-for="r in data.engineering.runs.filter(r=>r.format===f)" :key="r.round">{{r.seconds.toFixed(3)}}</td><td>{{data.engineering.medians[f].toFixed(3)}}</td></tr></tbody></table><p>每轮清除 Spark 显式缓存；未清除操作系统及 HDFS 缓存，首次观测不等于冷盘。转换耗时不计入查询时间；存储体积不等于实际扫描字节。</p><p>Standalone · 2 核 · 执行器/Driver 各 1 GB · 4 分区 · {{data.engineering.application_id}}</p></template></section>
  <section class="notice">数据来源：BTS Reporting Carrier · 实验完成 UTC：{{data.metrics.finished_at_utc}} · 配置 SHA256：{{data.metrics.config_sha256.slice(0,16)}}…</section>
  <section class="notice">单一半年划分与一个种子，未作统计显著性或跨年份泛化结论。历史档案回测未复原 BTS 当年的公开数据发布日期。B3 在主指标上优于 B2，F1 基本持平，B1 的 Brier 更低。</section>
 </div>
</template>
